import { describe, it, expect } from "vitest";
import { createChaseCamera } from "./chase-camera.js";
import { getViewMatrix } from "@babylonjs/lite";

const eye = { x: 0, y: 0, z: 0 };
const target = { x: 0, y: 0, z: 10 };
const dot = (a: number[], b: number[]) => a[0]! * b[0]! + a[1]! * b[1]! + a[2]! * b[2]!;
function axes(cam: any) {
  const w = cam.worldMatrix as any;
  return { x: [w[0], w[1], w[2]], y: [w[4], w[5], w[6]], z: [w[8], w[9], w[10]] };
}
describe("chase camera", () => {
  it("starts upright and looks at target", () => {
    const c = createChaseCamera(eye, target);
    const a = axes(c.camera);
    expect(a.y[1]).toBeCloseTo(1);
    expect(a.z[2]).toBeCloseTo(1);
  });
  it("banks to the requested up projected perpendicular to view", () => {
    const c = createChaseCamera(eye, target);
    c.bank({ x: 1, y: 0, z: 0 });
    const a = axes(c.camera);
    expect(a.y[0]).toBeCloseTo(1);
    expect(a.y[1]).toBeCloseTo(0);
    expect(dot(a.x, a.y)).toBeCloseTo(0);
    expect(a.z[2]).toBeCloseTo(1);
    // up with a component along the view: picture-up is the perpendicular part
    c.bank({ x: 0, y: 1, z: 1 });
    const b = axes(c.camera);
    expect(b.y[1]).toBeCloseTo(Math.SQRT1_2);
    expect(b.y[2]).toBeCloseTo(-Math.SQRT1_2);
  });
  it("keeps previous roll when up is along line of sight, either way", () => {
    const c = createChaseCamera(eye, target);
    c.bank({ x: 1, y: 0, z: 0 });
    const before = axes(c.camera);
    c.bank({ x: 0, y: 0, z: 1 });
    c.bank({ x: 0, y: 0, z: -3 });
    c.bank({ x: 0, y: 0, z: 1e6 });
    const after = axes(c.camera);
    expect(after.y).toEqual(before.y);
    expect(after.x).toEqual(before.x);
    expect(Number.isNaN(after.y[0])).toBe(false);
  });
  it("viewing through getViewMatrix stays finite", () => {
    const c = createChaseCamera(eye, target);
    c.bank({ x: 0, y: 0, z: 1 });
    const v = getViewMatrix(c.camera as any);
    expect(Array.from(v as any).every((n: any) => Number.isFinite(n))).toBe(true);
  });
});
EOF
